/*
 * A042458  Numerators of continued fraction convergents to sqrt(757).
 * https://oeis.org/A042458
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   Numerators of continued fraction convergents of sqrt(757). a(0)
 *            = 27. For n >= 1: a(n) = c_n * a(n-1) + a(n-2) where c_n are the
 *            partial quotients in the continued fraction expansion of
 *            sqrt(757) (a0 = 27). The partial quotients are generated by the
 *            standard quadratic‑surd algorithm: m_{k+1} = d_...
 * Range:     u8 n <= 2, u16 n <= 7, u32 n <= 15, u64 n <= 32, u128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    /* Handle the first element explicitly. */
    if (n == 0) return (seq_t)27;

    /* Constants for sqrt(757). */
    const idx_t D  = 757;
    const idx_t a0 = 27;

    /* Variables for the continued‑fraction algorithm. */
    idx_t m = 0;
    idx_t d = 1;
    idx_t a_k = a0;   /* current partial quotient (a_k). */

    /* Numerators of the convergents: p_{-1} = 1, p_0 = a0. */
    seq_t p_prevprev = 1;   /* p_{-1} */
    seq_t p_prev     = a0;  /* p_0 */

    /* Generate partial quotients and numerators up to index n. */
    for (idx_t i = 1; i <= n; ++i) {
        /* Next partial‑quotient parameters. */
        idx_t m_next = d * a_k - m;
        idx_t d_next = (D - m_next * m_next) / d;
        idx_t a_next = (a0 + m_next) / d_next;

        /* Rotate state for the next iteration. */
        m = m_next;
        d = d_next;
        a_k = a_next;

        /* Compute the current numerator. */
        seq_t p_curr = (seq_t)a_next * p_prev + p_prevprev;
        p_prevprev = p_prev;
        p_prev = p_curr;
    }

    return p_prev;
}
